text:
Here's your water tracker: tap a glass to log it, and it counts toward your goal of 8 glasses.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: Segoe UI, sans-serif; margin: 0; padding: 20px; text-align: center; color: #1b3a4b; }
  h1 { font-size: 20px; margin: 0 0 4px; }
  #date { font-size: 13px; opacity: .7; margin-bottom: 16px; }
  #count { font-size: 40px; font-weight: 600; margin: 8px 0; }
  #glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin: 16px 0; }
  .g { width: 44px; height: 60px; border: 2px solid #3b8fc4; border-radius: 4px 4px 12px 12px; background: #fff; cursor: pointer; padding: 0; }
  .g.full { background: #6ec1f0; }
  .bar { height: 10px; background: #e1eef7; border-radius: 5px; overflow: hidden; margin: 0 auto; max-width: 320px; }
  #fill { height: 100%; width: 0; background: #3b8fc4; transition: width .3s; }
  #msg { margin: 14px 0; min-height: 22px; font-size: 14px; }
  button.b { font-size: 15px; padding: 8px 16px; margin: 4px; border: 1px solid #3b8fc4; border-radius: 6px; background: #fff; color: #1b3a4b; cursor: pointer; }
  button.p { background: #3b8fc4; color: #fff; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div class="bar"><div id="fill"></div></div>
  <div id="glasses"></div>
  <div id="msg"></div>
  <button class="b p" id="add">+ Add a glass</button>
  <button class="b" id="sub">− Remove one</button>
  <button class="b" id="reset">Reset</button>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var key = "water-" + today;
  var n = 0;
  try { n = parseInt(localStorage.getItem(key) || "0", 10) || 0; } catch (e) {}
  document.getElementById("date").textContent = new Date().toDateString();

  function save() { try { localStorage.setItem(key, String(n)); } catch (e) {} }

  function draw() {
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    var total = Math.max(GOAL, n);
    for (var i = 0; i < total; i++) {
      var b = document.createElement("button");
      b.className = "g" + (i < n ? " full" : "");
      b.setAttribute("aria-label", "Glass " + (i + 1));
      (function (idx) {
        b.onclick = function () { n = (n === idx + 1) ? idx : idx + 1; save(); draw(); };
      })(i);
      box.appendChild(b);
    }
    var m = document.getElementById("msg");
    if (n >= GOAL) m.textContent = "Goal reached. Well done! 💧";
    else m.textContent = (GOAL - n) + " more to go.";
  }

  document.getElementById("add").onclick = function () { n++; save(); draw(); };
  document.getElementById("sub").onclick = function () { if (n > 0) n--; save(); draw(); };
  document.getElementById("reset").onclick = function () { n = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```

It resets each day. If your screen doesn't keep what you log after you close it, tell me and I'll adjust.
